css:
.mindmarket-sim-container {
    padding: 20px;
    background: linear-gradient(135deg, #0f0c29 0%, #302b63 50%, #24243e 100%);
    min-height: 100vh;
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;
    color: #e0e0e0;
}

.mindmarket-sim-header {
    background: linear-gradient(135deg, #667eea 0%, #764ba2 100%);
    color: white;
    padding: 30px;
    border-radius: 20px;
    margin-bottom: 20px;
    box-shadow: 0 8px 32px rgba(102,126,234,0.3);
    text-align: center;
}

.mindmarket-sim-header h1 { margin: 0 0 5px 0; font-size: 1.8rem; }
.mindmarket-sim-header p { margin: 0; opacity: 0.9; font-size: 0.95rem; }

.mindmarket-sim-period-counter {
    text-align: center;
    font-size: 1.1rem;
    margin-bottom: 20px;
    color: #b0b0cc;
}

.mindmarket-sim-status-cards {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(160px, 1fr));
    gap: 15px;
    margin-bottom: 20px;
}

.mindmarket-sim-status-card {
    background: rgba(255,255,255,0.08);
    border-radius: 12px;
    padding: 18px 14px;
    box-shadow: 0 3px 10px rgba(0,0,0,0.2);
    text-align: center;
    transition: transform 0.2s ease;
    backdrop-filter: blur(10px);
    border: 1px solid rgba(255,255,255,0.1);
}

.mindmarket-sim-status-card:hover { transform: translateY(-3px); }

.mindmarket-sim-label {
    color: #9999bb;
    font-size: 0.78rem;
    text-transform: uppercase;
    margin-bottom: 6px;
    letter-spacing: 0.5px;
}

.mindmarket-sim-value {
    font-size: 1.7rem;
    font-weight: 700;
    color: #fff;
}

.mindmarket-sim-card-primary { border-left: 4px solid #667eea; }
.mindmarket-sim-card-primary .mindmarket-sim-value { color: #667eea; }
.mindmarket-sim-card-ethics { border-left: 4px solid #f093fb; }
.mindmarket-sim-card-ethics .mindmarket-sim-value { color: #f093fb; }

.mindmarket-sim-briefing {
    background: rgba(255,255,255,0.06);
    border-left: 5px solid #667eea;
    border-radius: 10px;
    padding: 20px;
    margin-bottom: 15px;
    box-shadow: 0 2px 8px rgba(0,0,0,0.15);
}

.mindmarket-sim-briefing h4 { color: #667eea; margin: 0 0 10px 0; }
.mindmarket-sim-briefing p, .mindmarket-sim-briefing div { color: #c0c0d8; line-height: 1.6; }

.mindmarket-sim-data-panel {
    background: rgba(255,255,255,0.04);
    border: 1px solid rgba(102,126,234,0.3);
    border-radius: 10px;
    padding: 20px;
    margin-bottom: 20px;
    overflow-x: auto;
}

.mindmarket-sim-data-panel h4 { color: #a0a0cc; margin: 0 0 15px 0; font-size: 1rem; text-transform: uppercase; letter-spacing: 1px; }

.mindmarket-sim-data-panel table {
    width: 100%;
    border-collapse: collapse;
    font-size: 0.85rem;
    color: #d0d0e8;
}

.mindmarket-sim-data-panel table th {
    background: rgba(102,126,234,0.2);
    color: #667eea;
    padding: 8px 10px;
    text-align: left;
    font-weight: 600;
    border-bottom: 2px solid rgba(102,126,234,0.3);
}

.mindmarket-sim-data-panel table td {
    padding: 7px 10px;
    border-bottom: 1px solid rgba(255,255,255,0.06);
}

.mindmarket-sim-data-panel table tr:hover { background: rgba(255,255,255,0.04); }

.mindmarket-sim-controls {
    background: rgba(255,255,255,0.08);
    border-radius: 15px;
    padding: 25px;
    margin-bottom: 15px;
    box-shadow: 0 3px 10px rgba(0,0,0,0.2);
}

.mindmarket-sim-controls h3 { color: #667eea; margin: 0 0 20px 0; font-size: 1.2rem; }

.mindmarket-sim-controls label {
    display: block;
    font-weight: 600;
    color: #b0b0cc;
    margin-bottom: 6px;
    margin-top: 14px;
    font-size: 0.9rem;
}

.mindmarket-sim-controls select, .mindmarket-sim-controls textarea {
    background: rgba(255,255,255,0.1);
    border: 1px solid rgba(255,255,255,0.2);
    color: #e0e0f0;
    border-radius: 8px;
    padding: 8px 12px;
    width: 100%;
    max-width: 500px;
}

.mindmarket-sim-controls select option { background: #302b63; color: #e0e0f0; }

.mindmarket-sim-confidence {
    background: rgba(255,255,255,0.05);
    border-radius: 10px;
    padding: 15px 20px;
    margin-bottom: 15px;
}

.mindmarket-sim-confidence label {
    font-weight: 600;
    color: #b0b0cc;
    margin-bottom: 6px;
    display: block;
    font-size: 0.9rem;
}

.mindmarket-sim-confidence select {
    background: rgba(255,255,255,0.1);
    border: 1px solid rgba(255,255,255,0.2);
    color: #e0e0f0;
    border-radius: 8px;
    padding: 8px 12px;
    max-width: 200px;
}

.mindmarket-sim-confidence select option { background: #302b63; color: #e0e0f0; }

.mindmarket-sim-submit-btn {
    background: linear-gradient(135deg, #667eea, #764ba2) !important;
    border: none !important;
    font-size: 1.1rem;
    padding: 12px;
    border-radius: 10px !important;
    color: white;
}

.mindmarket-sim-submit-btn:hover {
    background: linear-gradient(135deg, #7b93ff, #8b5fbf) !important;
}

.mindmarket-sim-feedback {
    background: rgba(255,255,255,0.06);
    border-left: 5px solid #f093fb;
    border-radius: 10px;
    padding: 20px;
    margin: 20px 0;
}

.mindmarket-sim-feedback h4 { color: #f093fb; margin: 0 0 10px 0; }
.mindmarket-sim-feedback div { color: #c0c0d8; line-height: 1.5; }

.mindmarket-sim-history {
    background: rgba(255,255,255,0.06);
    border-radius: 12px;
    padding: 20px;
    margin-bottom: 20px;
}

.mindmarket-sim-history h4 { color: #b0b0cc; margin: 0 0 15px 0; }

.mindmarket-sim-charts-row {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 20px;
    margin-bottom: 20px;
}

.mindmarket-sim-chart-box {
    background: rgba(255,255,255,0.06);
    border-radius: 12px;
    padding: 20px;
}

.mindmarket-sim-chart-box canvas { max-height: 280px; }

.mindmarket-sim-highlight { color: #667eea; font-weight: 700; }
.mindmarket-sim-warning { color: #ffa726; font-weight: 600; }
.mindmarket-sim-positive { color: #66bb6a; }
.mindmarket-sim-negative { color: #ef5350; }

@media (max-width: 768px) {
    .mindmarket-sim-status-cards { grid-template-columns: repeat(2, 1fr); }
    .mindmarket-sim-charts-row { grid-template-columns: 1fr; }
    .mindmarket-sim-header h1 { font-size: 1.3rem; }
}
/* v2.0.0 additions (2026-11-10): focus, motion, readout, debrief. Append-only. */
.mindmarket-sim-container :focus-visible { outline: 3px solid #ffd166; outline-offset: 2px; }
.mindmarket-sim-container select, .mindmarket-sim-container button { min-height: 44px; }
.mindmarket-sim-container select { color-scheme: dark; }
.mindmarket-sim-confidence select { max-width: 100%; width: 100%; }
.mindmarket-sim-readout { margin-top: 12px; padding: 10px 14px; border-radius: 8px; background: rgba(240,147,251,0.10); border: 1px solid rgba(240,147,251,0.35); color: #e6e6f5; }
.mindmarket-sim-readout ul { margin: 6px 0 0 18px; padding: 0; }
.mindmarket-sim-cm { background: #1f1b45; color: #f0f0fa; padding: 18px; border-radius: 12px; text-align: left; line-height: 1.5; }
.mindmarket-sim-cm h3, .mindmarket-sim-cm h4 { color: #c9d1ff; margin: 14px 0 6px 0; }
.mindmarket-sim-cm h3 { margin-top: 0; font-size: 1.2rem; }
.mindmarket-sim-cm h4 { font-size: 1rem; }
.mindmarket-sim-cm p, .mindmarket-sim-cm li { color: #f0f0fa; }
.mindmarket-sim-cm-score-num { font-size: 2.2rem; font-weight: 700; color: #ffffff; }
.mindmarket-sim-cm-score-max { color: #c9c9e0; }
.mindmarket-sim-cm-verdict { display: inline-block; margin-left: 10px; padding: 2px 12px; border-radius: 999px; border: 1px solid #c9d1ff; color: #ffffff; font-weight: 600; }
.mindmarket-sim-cm-strip { display: flex; flex-wrap: wrap; gap: 8px; margin: 8px 0; }
.mindmarket-sim-cm-chip { flex: 1 1 120px; background: #2c2760; border-radius: 8px; padding: 8px 10px; }
.mindmarket-sim-cm-chip-label { display: block; font-size: 0.75rem; color: #c9c9e0; }
.mindmarket-sim-cm-chip-value { display: block; font-size: 1.05rem; font-weight: 700; color: #ffffff; }
.mindmarket-sim-cm-next { margin-top: 12px; padding-top: 10px; border-top: 1px solid #4a4590; }
@media (max-width: 480px) { .mindmarket-sim-container { padding: 16px; } .mindmarket-sim-header { padding: 18px; } .mindmarket-sim-controls { padding: 16px; } }
@media (prefers-reduced-motion: reduce) { .mindmarket-sim-status-card { transition: none; } .mindmarket-sim-status-card:hover { transform: none; } }
.mindmarket-sim-history { overflow-x: auto; }
.mindmarket-sim-history table.table { color: #e6e6f5; margin-bottom: 0; }
.mindmarket-sim-history table.table th, .mindmarket-sim-history table.table td { color: #e6e6f5; background-color: transparent; box-shadow: none; border-color: rgba(255,255,255,0.12); }
.mindmarket-sim-history table.table th { color: #c9d1ff; }
.mindmarket-sim-history table.table tbody tr:nth-of-type(odd) { background-color: rgba(255,255,255,0.07); }
.mindmarket-sim-history table.table tbody tr:nth-of-type(even) { background-color: transparent; }
.mindmarket-sim-charts-row { grid-template-columns: minmax(0, 1fr) minmax(0, 1fr); }
.mindmarket-sim-chart-box { min-width: 0; }
.mindmarket-sim-chart-box canvas { max-width: 100%; }
@media (max-width: 768px) { .mindmarket-sim-charts-row { grid-template-columns: minmax(0, 1fr); } }

