        }
    ];

    var ANSWER_KEY = {
        r1: { 'C-3': 5, 'C-1': 4, 'C-5': 3, 'C-4': 2, 'C-2': 1 },
        r2: { 'P-6': 5, 'P-4': 4.5, 'P-3': 4, 'P-8': 3.5, 'P-5': 3, 'P-2': 2.5, 'P-9': 2, 'P-7': 1.5, 'P-1': 1 },
        r3shelf: { 'B': 5, 'A': 2, 'C': 3 },
        r3ux: { 'V-2': 5, 'V-4': 4, 'V-3': 3, 'V-1': 1 },
        r3ethics: { 'principled': 2, 'generic': 1, 'commercial': 0 },
        r4schedule: { 'variable': 5, 'social': 4, 'progressive': 3, 'fixed': 2 },
        r4overfit: { 'gsr_arousal': 5, 'eeg_aai': 4, 'eye_fixation': 4, 'iat_association': 3, 'survey_data': 2 }
    };

    // Points model (v2.0.0). One function, _recompute, derives every total, the launch score, the
    // band and the delayed costs from the per-round records kept by index in domainState.rounds.
    // Launch score 0-100 = decision quality 50 + ethics 20 + calibration 14 + self-critique 16
    // minus the delayed costs of weak commitments, which land one or two rounds later.
    var DRAG_K = 4;
    var BANDS = [
        { min: 90, key: 'perf_excellent' },
        { min: 70, key: 'perf_good' },
        { min: 50, key: 'perf_moderate' },
        { min: -1, key: 'perf_developing' }
    ];
    var OPT_KEYS = {
        'C-1': 'opt_c1', 'C-2': 'opt_c2', 'C-3': 'opt_c3', 'C-4': 'opt_c4', 'C-5': 'opt_c5',
        'P-1': 'opt_p1', 'P-2': 'opt_p2', 'P-3': 'opt_p3', 'P-4': 'opt_p4', 'P-5': 'opt_p5',
        'P-6': 'opt_p6', 'P-7': 'opt_p7', 'P-8': 'opt_p8', 'P-9': 'opt_p9',
        'A': 'opt_shelf_a', 'B': 'opt_shelf_b', 'C': 'opt_shelf_c',
        'V-1': 'opt_ux_v1', 'V-2': 'opt_ux_v2', 'V-3': 'opt_ux_v3', 'V-4': 'opt_ux_v4',
        'principled': 'opt_ethics_principled', 'generic': 'opt_ethics_generic', 'commercial': 'opt_ethics_commercial',
        'fixed': 'opt_sched_fixed', 'variable': 'opt_sched_variable', 'progressive': 'opt_sched_progressive', 'social': 'opt_sched_social',
        'gsr_arousal': 'opt_of_gsr', 'eeg_aai': 'opt_of_eeg', 'eye_fixation': 'opt_of_eye', 'iat_association': 'opt_of_iat', 'survey_data': 'opt_of_survey'
    };

    function mmRound1(v) { return Math.round(v * 10) / 10; }

    function mmCalibration(conf, q) {
        var n = q / 5;
        if (conf === 'high' && n < 0.5) return -1.5;
        if (conf === 'high' && n >= 0.7) return 2;
        if (conf === 'medium') return 1;
        if (conf === 'low' && n >= 0.7) return 0.5;
        if (conf === 'low' && n < 0.5) return 1;
        return 0.5;
    }

    function mmDrag(q) { return DRAG_K * Math.max(0, 3 - q); }

    function mmBand(score) {
        for (var i = 0; i < BANDS.length; i++) { if (score >= BANDS[i].min) return BANDS[i].key; }
        return 'perf_developing';
    }

    class MindMarketAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = 'MindMarket: Neuromarketing & Decision Neuroscience';
            this.version = '2.0.0';
        }

        _t(key, params) {
            return (window.mySimulation && window.mySimulation.t) ? window.mySimulation.t(key, params) : key;
        }

        _lang() {
            // the framework keeps no language property: vcI18n is the live source
            var l = (window.vcI18n && window.vcI18n._lang) || (window.mySimulation && window.mySimulation.lang) || document.documentElement.lang || 'en';
            return String(l).slice(0, 2).toLowerCase();
        }

        _f(key, vars) {
            var s = String(this._t(key));
            Object.keys(vars || {}).forEach(function(k) { s = s.split('{' + k + '}').join(String(vars[k])); });
            return s;
        }

        _num(v) {
            var s = String(mmRound1(v));
            return this._lang() === 'es' ? s.replace('.', ',') : s;
        }

        _optLabel(value) {
            if (!value || !OPT_KEYS[value]) return value || '--';
            return String(this._t(OPT_KEYS[value])).split(':')[0];
        }

        _ds() {
            var st = window.mySimulation && window.mySimulation.state;
            return (st && st.domainState) || {};
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    rounds: [],
                    totalScore: 0,
                    dqsTotal: 0,
                    calibrationTotal: 0,
                    ethicsScore: 0,
                    overFitScore: 0,
                    dragTotal: 0,
                    launchSuccess: 0,
                    outcomeScore: 0,
                    processScore: 0,
                    ethicsSubmitted: false,
                    performanceTier: ''
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                state.decisions = {
                    mainChoice: '',
                    secondChoice: '',
                    ethicsChoice: '',
                    overfitChoice: '',
                    confidence: ''
                };
            }
            this._bindOnce();
            this._updateBriefing(state);
        }

        _bindOnce() {
            if (this._bound) return;
            this._bound = true;
            var self = this;
            var repaint = function() {
                try {
                    var st = window.mySimulation && window.mySimulation.state;
                    if (!st) return;
                    self._updateBriefing(st, true);
                    self._renderFeedback(st);
                } catch (e) { /* repaint is best effort */ }
            };
            document.addEventListener('express:langchanged', function() { setTimeout(repaint, 0); });
            setTimeout(function() {
                try {
                    var bus = window.mySimulation && window.mySimulation.eventBus;
                    if (bus && bus.on) {
                        bus.on('language:changed', function() { setTimeout(repaint, 0); });
                        // an undone round needs its own controls back before the player touches them
                        bus.on('period:undone', function() {
                            repaint();
                            // the controls of the undone round were just rebuilt: let the shared guard
                            // register them now, before the player can touch them
                            try { if (typeof __eqilGuard !== 'undefined' && __eqilGuard.pass) { __eqilGuard.pass(); } } catch (e) { /* guard absent */ }
                        });
                    }
                } catch (e) { /* no event bus in this runtime */ }
            }, 0);
        }

        // Soft-launch readout: the symptom of an earlier commitment, shown before the round it lands in.
        _readoutHtml(period, ds) {
            var rounds = (ds && ds.rounds) || [];
            var lines = [];
            var self = this;
            var line = function(okKey, badKey, drag) {
                lines.push(drag > 0 ? self._f(badKey, { n: Math.round(drag * 3) }) : self._t(okKey));
            };
            if (period === 3 && rounds[0]) {
                line('readout_r1_ok', 'readout_r1_bad', mmDrag(rounds[0].q));
            }
            if (period === 4 && rounds[1]) {
                line('readout_r2_ok', 'readout_r2_bad', mmDrag(rounds[1].q));
            }
            if (period === 4 && rounds[2]) {
                line('readout_r3_ok', 'readout_r3_bad', mmDrag(rounds[2].shelfQ) + mmDrag(rounds[2].uxQ));
            }
            if (!lines.length) return '';
            return '<div class="mindmarket-sim-readout"><strong>' + this._t('readout_title') + '</strong><ul><li>' + lines.join('</li><li>') + '</li></ul></div>';
        }

        _updateBriefing(state, keepSelections) {
            var st = (window.mySimulation && window.mySimulation.state) || state || {};
            var ds = (state && state.domainState) || st.domainState || {};
            // the run is over when the real history holds every round, as the engine itself decides
            var done = !!(st.history && st.history.length >= ROUNDS.length);
            var period = Math.min((state && state.currentPeriod) || 1, ROUNDS.length);
            var round = ROUNDS[period - 1];
            var isEs = this._lang() === 'es';

            var titleEl = document.getElementById('briefingTitle');
            var textEl = document.getElementById('briefingText');
            var dataEl = document.getElementById('dataContent');
            var dynEl = document.getElementById('dynamicControls');
            var show = function(id, on) { var el = document.getElementById(id); if (el) el.style.display = on ? '' : 'none'; };

            var self = this;
            [['scoreChart', 'chart_alt_score'], ['calibrationChart', 'chart_alt_cal']].forEach(function(pair) {
                var cv = document.getElementById(pair[0]);
                var txt = self._t(pair[1]);
                if (cv && txt !== pair[1]) { cv.setAttribute('role', 'img'); cv.setAttribute('aria-label', txt); }
            });
            show('dataPanel', !done);
            show('controlsPanel', !done);
            show('confidencePanel', !done);

            if (done) {
                if (titleEl) titleEl.textContent = this._t('end_title');
                if (textEl) textEl.innerHTML = this._t('end_text');
                return;
            }

            if (titleEl) titleEl.textContent = (isEs && round.titleEs) ? round.titleEs : round.title;
            if (textEl) textEl.innerHTML = ((isEs && round.briefingEs) ? round.briefingEs : round.briefing) + this._readoutHtml(period, ds);
            if (dataEl) dataEl.innerHTML = (isEs && round.dataHtmlEs) ? round.dataHtmlEs : round.dataHtml;

            if (!dynEl) return;

            var t = this._t.bind(this);
            if (keepSelections && dynEl.getAttribute('data-round') === String(period)) {
                // same round, new language: refresh the texts in place and leave the selections alone
                Array.prototype.forEach.call(dynEl.querySelectorAll('select'), function(selEl) {
                    Array.prototype.forEach.call(selEl.options, function(o) {
                        if (o.value && OPT_KEYS[o.value]) o.textContent = t(OPT_KEYS[o.value]);
                        else if (!o.value && selEl.getAttribute('data-ph')) o.textContent = t(selEl.getAttribute('data-ph'));
                    });
                });
                if (window.mySimulation && window.mySimulation.applyTranslations) { window.mySimulation.applyTranslations(); }
                return;
            }

            var html = '';
            var sel = function(id, labelKey, phKey, opts) {
                var h = '<label for="' + id + '" data-i18n="' + labelKey + '">' + t(labelKey) + '</label>';
                h += '<select id="' + id + '" class="form-control" data-ph="' + phKey + '">';
                h += '<option value="">' + t(phKey) + '</option>';
                opts.forEach(function(v) { h += '<option value="' + v + '">' + t(OPT_KEYS[v]) + '</option>'; });
                return h + '</select>';
            };

            if (period === 1) {
                html += sel('creativeInput', 'r1_creative_label', 'ph_select_creative', ['C-1', 'C-2', 'C-3', 'C-4', 'C-5']);
            } else if (period === 2) {
                html += sel('frameInput', 'r2_frame_label', 'ph_select_frame', ['P-1', 'P-2', 'P-3', 'P-4', 'P-5', 'P-6', 'P-7', 'P-8', 'P-9']);
            } else if (period === 3) {
                html += sel('shelfInput', 'r3_shelf_label', 'ph_select_config', ['A', 'B', 'C']);
                html += sel('uxInput', 'r3_ux_label', 'ph_select_ux', ['V-1', 'V-2', 'V-3', 'V-4']);
                html += sel('ethicsInput', 'r3_ethics_label', 'ph_select_ethics', ['principled', 'generic', 'commercial']);
            } else if (period === 4) {
                html += sel('scheduleInput', 'r4_schedule_label', 'ph_select_schedule', ['fixed', 'variable', 'progressive', 'social']);
                html += sel('overfitInput', 'r4_overfit_label', 'ph_select_signal', ['gsr_arousal', 'eeg_aai', 'eye_fixation', 'iat_association', 'survey_data']);
            }

            dynEl.innerHTML = html;
            dynEl.setAttribute('data-round', String(period));
            // the labels above were just injected: applyTranslations only runs once at boot
            if (window.mySimulation && window.mySimulation.applyTranslations) { window.mySimulation.applyTranslations(); }
        }

        validateDecisions(decisions) {
            var st = window.mySimulation.state;
            var period = st.currentPeriod || 1;
            var warn = function(key) {
                window.mySimulation.uiManager.showNotification(window.mySimulation.t(key), 'warning');
                return false;
            };

            var val = function(id) { var el = document.getElementById(id); return el ? el.value : ''; };
            var mainId = period === 1 ? 'creativeInput' : period === 2 ? 'frameInput' : period === 3 ? 'shelfInput' : 'scheduleInput';
            decisions.mainChoice = val(mainId);
            decisions.secondChoice = period === 3 ? val('uxInput') : '';
            decisions.ethicsChoice = period === 3 ? val('ethicsInput') : '';
            decisions.overfitChoice = period === 4 ? val('overfitInput') : '';
            decisions.confidence = val('confidenceInput');

            if (!decisions.mainChoice) return warn('select_warning');
            if (period === 3 && (!decisions.secondChoice || !decisions.ethicsChoice)) return warn('all_fields_warning');
            if (period === 4 && !decisions.overfitChoice) return warn('overfit_warning');
            if (!decisions.confidence) return warn('confidence_warning');
            return true;
        }

        // Scores one round into its record. Pure with respect to the other rounds: same inputs, same record.
        _roundRecord(period, d) {
            var rec = { period: period, main: d.mainChoice, second: '', ethics: '', overfit: '', conf: d.confidence,
                q: 1, shelfQ: 0, uxQ: 0, eth: 0, of: 0, label: '' };
            if (period === 1) {
                rec.label = 'rl_ad_creative';
                rec.q = ANSWER_KEY.r1[d.mainChoice] || 1;
            } else if (period === 2) {
                rec.label = 'rl_pricing_frame';
                rec.q = ANSWER_KEY.r2[d.mainChoice] || 1;
            } else if (period === 3) {
                rec.label = 'rl_store_ux_ethics';
                rec.second = d.secondChoice;
                rec.ethics = d.ethicsChoice;
                rec.shelfQ = ANSWER_KEY.r3shelf[d.mainChoice] || 1;
                rec.uxQ = ANSWER_KEY.r3ux[d.secondChoice] || 1;
                rec.q = (rec.shelfQ + rec.uxQ) / 2;
                rec.eth = ANSWER_KEY.r3ethics[d.ethicsChoice] || 0;
            } else {
                rec.label = 'rl_loyalty_overfit';
                rec.overfit = d.overfitChoice;
                rec.q = ANSWER_KEY.r4schedule[d.mainChoice] || 1;
                rec.of = ANSWER_KEY.r4overfit[d.overfitChoice] || 1;
            }
            rec.cal = mmCalibration(d.confidence, rec.q);
            return rec;
        }

        // Re-sums everything from the round records: totals, delayed costs, launch score and band.
        _recompute(ds) {
            var rounds = ds.rounds || [];
            var dq = 0, cal = 0, eth = 0, of = 0, drag = 0, ethDone = false, ethRaw = 0, ofRaw = 0;
            for (var i = 0; i < rounds.length; i++) {
                var r = rounds[i];
                if (!r) continue;
                r.dqPts = 2.5 * r.q;
                r.calPts = r.cal + 1.5;
                r.ethPts = i === 2 ? 10 * r.eth : 0;
                r.ofPts = i === 3 ? 4 * (r.of - 1) : 0;
                r.dragPts = 0;
                if (i === 2 && rounds[0]) r.dragPts += mmDrag(rounds[0].q);
                if (i === 3 && rounds[1]) r.dragPts += mmDrag(rounds[1].q);
                if (i === 3 && rounds[2]) r.dragPts += mmDrag(rounds[2].shelfQ) + mmDrag(rounds[2].uxQ);
                r.total = r.dqPts + r.calPts + r.ethPts + r.ofPts - r.dragPts;
                dq += r.dqPts; cal += r.calPts; eth += r.ethPts; of += r.ofPts; drag += r.dragPts;
                if (i === 2) { ethDone = true; ethRaw = r.eth; }
                if (i === 3) { ofRaw = r.of; }
            }
            var score = Math.max(0, Math.min(100, Math.round(dq + cal + eth + of - drag)));
            var complete = rounds.filter(function(x) { return !!x; }).length >= ROUNDS.length;
            ds.dqsTotal = mmRound1(dq);
            ds.calibrationTotal = mmRound1(cal);
            ds.ethicsScore = ethRaw;
            ds.ethicsSubmitted = ethDone;
            ds.overFitScore = ofRaw;
            ds.dragTotal = mmRound1(drag);
            ds.totalScore = score;
            ds.outcomeScore = mmRound1(Math.max(0, dq + eth - drag));
            ds.processScore = mmRound1(cal + of);
            ds.launchSuccess = complete ? score : 0;
            ds.performanceTier = complete ? mmBand(score) : '';
            ds.performance = Object.assign({}, ds.performance || {}, { overallScore: score });
            return score;
        }

        _renderFeedback(state) {
            var feedPanel = document.getElementById('feedbackPanel');
            var feedTitle = document.getElementById('feedbackTitle');
            var feedContent = document.getElementById('feedbackContent');
            var rounds = ((state && state.domainState) || {}).rounds || [];
            var last = null;
            for (var i = rounds.length - 1; i >= 0; i--) { if (rounds[i]) { last = rounds[i]; break; } }
            if (!feedPanel) return;
            if (!last) { feedPanel.style.display = 'none'; return; }
            var p = last.period;
            var msg = '';
            if (p === 1) {
                msg = this._t('fb_r1_' + last.main);
            } else if (p === 2) {
                msg = this._t('fb_r2_' + last.main);
            } else if (p === 3) {
                msg = this._t('fb_prefix_shelf') + this._t(last.main === 'B' ? 'fb_shelf_b' : last.main === 'C' ? 'fb_shelf_c' : 'fb_shelf_default');
                msg += '<br><br>' + this._t('fb_prefix_ux') + this._t(last.second === 'V-2' ? 'fb_ux_v2' : last.second === 'V-4' ? 'fb_ux_v4' : last.second === 'V-1' ? 'fb_ux_v1' : 'fb_ux_default');
                msg += '<br><br>' + this._t('fb_prefix_ethics') + this._t('fb_ethics_' + last.ethics);
            } else {
                msg = this._t(last.main === 'variable' ? 'fb_sched_variable' : last.main === 'social' ? 'fb_sched_social' : last.main === 'progressive' ? 'fb_sched_progressive' : 'fb_sched_default');
                msg += '<br><br>' + this._t('fb_prefix_overfit') + this._t(last.overfit === 'gsr_arousal' ? 'fb_of_gsr' : last.overfit === 'eeg_aai' ? 'fb_of_eeg' : last.overfit === 'eye_fixation' ? 'fb_of_eye' : last.overfit === 'iat_association' ? 'fb_of_iat' : 'fb_of_default');
            }
            var extra = '';
            if (p === 3) extra += this._f('fb_points_eth', { eth: this._num(last.ethPts) });
            if (p === 4) extra += this._f('fb_points_of', { of: this._num(last.ofPts) });
            msg += '<br><br>' + this._f('fb_points', { pts: this._num(last.total), dq: this._num(last.dqPts), cal: this._num(last.calPts), extra: extra });
            if (last.dragPts > 0) msg += '<br>' + this._f('fb_drag_landed', { pts: this._num(last.dragPts) });
            if (p === 1) msg += '<br>' + this._f('fb_drag_future', { r: 3 });
            if (p === 2 || p === 3) msg += '<br>' + this._f('fb_drag_future', { r: 4 });
            feedPanel.style.display = 'block';
            if (feedTitle) feedTitle.textContent = this._t(last.label) + this._t('fb_analysis_suffix');
            if (feedContent) feedContent.innerHTML = msg;
        }

        calculateResults(state) {
            var d = state.decisions;
            var ds = state.domainState;
            var period = state.currentPeriod;
            if (!ds.rounds) ds.rounds = [];
            ds.rounds.length = Math.max(0, period - 1);
            var rec = this._roundRecord(period, d);
            ds.rounds[period - 1] = rec;
            var score = this._recompute(ds);
            this._renderFeedback(state);

            var self = this;
            setTimeout(((__eqilNext) => function() {
                self._updateBriefing({ currentPeriod: __eqilNext });
            })(state.currentPeriod + 1), 500);

            return {
                period: period,
                roundLabel: rec.label,
                mainChoice: rec.main,
                secondChoice: rec.second || '--',
                confidence: rec.conf,
                decisionQuality: mmRound1(rec.q),
                calibration: mmRound1(rec.cal),
                ethicsPoints: rec.eth,
                delayedCost: mmRound1(rec.dragPts),
                roundTotal: mmRound1(rec.total),
                cumulativeScore: score,
                overallScore: score,
                score: score
            };
        }

