        getChartData(state) {
            var ds = (state && state.domainState) || {};
            var rounds = (ds.rounds || []).filter(function(r) { return !!r; });
            var labels = rounds.map(function(r) { return 'R' + r.period; });
            return {
                scoreChart: {
                    labels: labels,
                    datasets: [
                        { data: rounds.map(function(r) { return mmRound1(r.dqPts || 0); }) },
                        { data: rounds.map(function(r) { return mmRound1(r.total || 0); }) }
                    ]
                },
