                    ]
                }
            };
        }

        // What each commitment cost, from the run itself: immediate shortfall, calibration lost on a
        // weak call, and the delayed cost. Used for the turning point and the insights.
        _findings(ds) {
            var rounds = ds.rounds || [];
            var out = [];
            var self = this;
            var add = function(r, kind, value, cost, mistake) {
                if (cost >= 2) out.push({ round: r, kind: kind, value: value, cost: mmRound1(cost), mistake: mistake || '' });
            };
            var calLoss = function(rec) { return rec.q < 5 ? Math.max(0, 2 - rec.cal) : 0; };
            if (rounds[0]) add(1, 'creative', rounds[0].main, (5 - rounds[0].q) * 2.5 + calLoss(rounds[0]) + mmDrag(rounds[0].q), rounds[0].main === 'C-2' ? 'm1' : '');
            if (rounds[1]) add(2, 'frame', rounds[1].main, (5 - rounds[1].q) * 2.5 + calLoss(rounds[1]) + mmDrag(rounds[1].q), rounds[1].main === 'P-7' ? 'm2' : '');
            if (rounds[2]) {
                var r3 = rounds[2];
                var shelfLower = r3.shelfQ <= r3.uxQ;
                add(3, 'shelf', r3.main, (5 - r3.shelfQ) * 1.25 + mmDrag(r3.shelfQ) + (shelfLower ? calLoss(r3) : 0), '');
                add(3, 'ux', r3.second, (5 - r3.uxQ) * 1.25 + mmDrag(r3.uxQ) + (shelfLower ? 0 : calLoss(r3)), r3.second === 'V-1' ? 'm3' : '');
                add(3, 'ethics', r3.ethics, (2 - r3.eth) * 10, r3.ethics === 'commercial' ? 'm4' : '');
            }
            if (rounds[3]) {
                add(4, 'schedule', rounds[3].main, (5 - rounds[3].q) * 2.5 + calLoss(rounds[3]), '');
                add(4, 'overfit', rounds[3].overfit, (5 - rounds[3].of) * 4, rounds[3].overfit === 'survey_data' ? 'm5' : '');
            }
            out.sort(function(a, b) { return b.cost - a.cost; });
            return out.map(function(f) {
                f.text = f.mistake ? self._f('cm_tp_' + f.mistake, { pts: self._num(f.cost) })
                    : self._f('cm_gen', { r: f.round, choice: self._optLabel(f.value), pts: self._num(f.cost) });
                return f;
            });
        }

        _insights(ds, findings) {
            var rounds = ds.rounds || [];
            var out = findings.slice(1, 4).map(function(f) { return f.text; });
            var pos = [];
            if (rounds[0] && rounds[0].main === 'C-3') pos.push(this._t('cm_pos_r1'));
            if (rounds[1] && rounds[1].main === 'P-6') pos.push(this._t('cm_pos_r2'));
            if (rounds[2] && rounds[2].main === 'B' && rounds[2].second === 'V-2') pos.push(this._t('cm_pos_r3'));
            if (rounds[2] && rounds[2].ethics === 'principled') pos.push(this._t('cm_pos_eth'));
            if (rounds[3] && rounds[3].overfit === 'gsr_arousal') pos.push(this._t('cm_pos_r4'));
            while (out.length < 4 && pos.length) out.push(pos.shift());
            var sound = 0, weak = 0, played = 0;
            rounds.forEach(function(r) {
                if (!r) return;
                played++;
                if (r.conf === 'high' && r.q / 5 >= 0.7) sound++;
                if (r.conf === 'high' && r.q / 5 < 0.5) weak++;
            });
            out.push(this._f('cm_cal', { a: sound, b: weak, n: played }));
            return out;
        }

        getPerformanceSummary(history) {
            if (!history || history.length === 0) return {};
            var ds = this._ds();
            var score = (ds.performance && typeof ds.performance.overallScore === 'number') ? ds.performance.overallScore : (ds.totalScore || 0);
            var key = mmBand(score);
            var findings = this._findings(ds);
            return {
                composite: score,
                overallScore: score,
                totalScore: score,
                score: score,
                launchSuccess: score,
                performance: key,
                performanceKey: key,
                performanceLabel: this._t(key),
                outcome: ds.outcomeScore || 0,
                process: ds.processScore || 0,
                turningPoint: findings.length ? findings[0].text : this._t('cm_turning_none'),
                insights: this._insights(ds, findings),
                ethicsScore: (ds.ethicsScore || 0) + '/2',
                overFitDefense: (ds.overFitScore || 0) + '/5',
                delayedCosts: ds.dragTotal || 0
            };
        }

        formatCompletionMessage(summary) {
            var s = summary || {};
            var ds = this._ds();
            var self = this;
            var t = this._t.bind(this);
            var esc = function(x) { return String(x).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;'); };
            var chip = function(labelKey, value) {
                return '<div class="mindmarket-sim-cm-chip"><span class="mindmarket-sim-cm-chip-label">' + t(labelKey) + '</span><span class="mindmarket-sim-cm-chip-value">' + value + '</span></div>';
            };
            var score = typeof s.overallScore === 'number' ? s.overallScore : (ds.totalScore || 0);
            var h = '<div class="mindmarket-sim-cm">';
            h += '<h3 class="mindmarket-sim-cm-title">' + t('completion_title') + '</h3>';
            h += '<p class="mindmarket-sim-cm-score"><span class="mindmarket-sim-cm-score-num">' + score + '</span><span class="mindmarket-sim-cm-score-max">/100</span> <span class="mindmarket-sim-cm-verdict">' + esc(s.performanceLabel || t(mmBand(score))) + '</span></p>';
            h += '<div class="mindmarket-sim-cm-strip">';
            h += chip('cm_outcome', self._num(ds.outcomeScore || 0) + '/70');
            h += chip('cm_process', self._num(ds.processScore || 0) + '/30');
            h += '</div><div class="mindmarket-sim-cm-strip">';
            h += chip('cm_k_dq', self._num(ds.dqsTotal || 0) + '/50');
            h += chip('cm_k_eth', self._num((ds.ethicsScore || 0) * 10) + '/20');
            h += chip('cm_k_cal', self._num(ds.calibrationTotal || 0) + '/14');
            h += chip('cm_k_of', self._num(Math.max(0, ((ds.overFitScore || 1) - 1) * 4)) + '/16');
            h += chip('cm_k_drag', (ds.dragTotal > 0 ? '-' : '') + self._num(ds.dragTotal || 0));
            h += '</div>';
            h += '<h4>' + t('cm_turning') + '</h4><p>' + esc(s.turningPoint || t('cm_turning_none')) + '</p>';
            h += '<h4>' + t('cm_insights') + '</h4><ul>';
            (s.insights || []).forEach(function(line) { h += '<li>' + esc(line) + '</li>'; });
            h += '</ul>';
            h += '<h4>' + t('cm_q_title') + '</h4><ol><li>' + t('cm_q1') + '</li><li>' + t('cm_q2') + '</li><li>' + t('cm_q3') + '</li></ol>';
            h += '<p class="mindmarket-sim-cm-next">' + t('cm_next') + '</p>';
            return h + '</div>';
        }

        getHint(state, results) {
